{
  "name": "design-eng-skills",
  "version": "0.1.0",
  "private": true,
  "description": "Agent skills: state machine design, changeset writing, engineering writing, component API design",
  "repository": {
    "type": "git",
    "url": "https://github.com/segunadebayo/design-eng-skills"
  },
  "license": "MIT",
  "scripts": {
    "changeset": "changeset",
    "version": "changeset version"
  },
  "devDependencies": {
    "@changesets/changelog-github": "^0.7.0",
    "@changesets/cli": "^2.30.0"
  },
  "packageManager": "yarn@1.22.22+sha512.a6b2f7906b721bba3d67d4aff083df04dad64c399707841b7acf00f6b133b7ac24255f2652fa22ae3534329dc6180534e98d17432037ff6fd140556e2bb3137e"
}

import nextConfig from '@next/eslint-plugin-next';
import reactPlugin from 'eslint-plugin-react';

export default [
  {
    plugins: {
      '@next/next': nextConfig,
      react: reactPlugin,
    },
    rules: {
      ...nextConfig.configs.recommended.rules,
      ...nextConfig.configs['core-web-vitals'].rules,
      'react/prop-types': 'off',
      'react/no-unescaped-entities': 'off',
    },
  },
];

class VeliteWebpackPlugin {
  static started = false;
  /** @param {import('webpack').Compiler} compiler */
  apply(compiler) {
    compiler.hooks.beforeCompile.tapPromise('VeliteWebpackPlugin', async () => {
      if (VeliteWebpackPlugin.started) return;
      VeliteWebpackPlugin.started = true;
      const dev = compiler.options.mode === 'development';
      const { build } = await import('velite');
      await build({ watch: dev, clean: !dev });
    });
  }
}

/**
 * @type {import('next').NextConfig}
 */
module.exports = {
  experimental: {
    optimizePackageImports: ['@chakra-ui/react'],
  },
  webpack: (config) => {
    config.plugins.push(new VeliteWebpackPlugin());
    return config;
  },
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: 'pbs.twimg.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'vercel.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'i.ytimg.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'images.unsplash.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'og-image-react-egghead.vercel.app',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'images.ctfassets.net',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'secure.meetupstatic.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'cdn.changelog.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'speakeasyjs.com',
        pathname: '/**',
      },
      {
        protocol: 'https',
        hostname: 'opengraph.githubassets.com',
        pathname: '/**',
      },
    ],
  },
};

{
  "name": "bundle-n-require",
  "version": "1.1.2",
  "description": "Require and bundle Typescript and Javascript files in NodeJS",
  "main": "dist/index.js",
  "module": "dist/index.mjs",
  "scripts": {
    "build": "tsup src --format cjs,esm --shims --dts",
    "pub": "pnpm build && pnpm publish --no-git-checks --access public",
    "clean": "rimraf dist"
  },
  "keywords": [
    "esbuild",
    "tsup",
    "require",
    "bundle",
    "nodejs"
  ],
  "files": [
    "dist"
  ],
  "publishConfig": {
    "access": "public"
  },
  "author": "Segun Adebayo <joseshegs@gmail.com>",
  "license": "MIT",
  "dependencies": {
    "esbuild": "^0.25.1",
    "node-eval": "^2.0.0"
  },
  "devDependencies": {
    "@types/node": "^22.13.10",
    "rimraf": "^6.0.1",
    "tsup": "^8.4.0",
    "typescript": "^5.8.2"
  },
  "packageManager": "pnpm@9.15.6+sha512.139cab068fdf0b751268179ac5f909b5be72afb4a75c513d1905d151befc8977b593d3cf8671ed83d4d6637c5c94b98ffbce108125de4a5a27a31233601a99de"
}

